input.value:
fetch dt.davis.problems
| dedup {display_id}, sort:{timestamp desc}
| fieldsAdd rc=if(isNotNull(root_cause_entity_id) or isNotNull(root_cause.smartscape_entity.id),1.0,else:0.0), im=if(arraySize(affected_entity_ids)>1 or arraySize(smartscape.affected_entity.ids)>1,1.0,else:0.0), ac=if(dt.davis.mute.status=="NOT_MUTED" and dt.davis.is_duplicate==false and dt.davis.is_frequent_event==false,1.0,else:0.0)
| summarize PUI=round(0.4*avg(rc)+0.3*avg(im)+0.3*avg(ac),decimals:3), problems=count(), by:{week=bin(timestamp,7d)}
| sort week asc

fetch dt.system.events
| filter event.kind=="AUDIT_EVENT" and isNull(authentication.token) and isNotNull(details.dt.settings.object_summary)
| filterOut in(user.id, {"UNKNOWN","system"})
| summarize changes=count(), by:{user.id, week=bin(timestamp,7d)}
| summarize COC=round(sum(changes*changes)/(sum(changes)*sum(changes)),decimals:3), participants=countDistinct(user.id), by:{week}
| sort week asc
